import copy


class PatchError(Exception):
    pass


def apply_patch(document, operations):
    result = copy.deepcopy(document)
    for operation in operations:
        op = operation["op"]
        path = operation["path"].strip("/").split("/") if operation["path"] else []
        target = result
        for part in path[:-1]:
            target = target[int(part)] if isinstance(target, list) else target[part]
        key = path[-1] if path else None
        if op in {"add", "replace"}:
            if key is None:
                result = operation["value"]
            elif isinstance(target, list):
                target[int(key)] = operation["value"]
            else:
                target[key] = operation["value"]
        elif op == "remove":
            if isinstance(target, list):
                target.pop(int(key))
            else:
                del target[key]
    return result

import copy


class PatchError(Exception):
    pass


def _parse_pointer(pointer):
    if pointer == "":
        return []
    if not isinstance(pointer, str) or not pointer.startswith("/"):
        raise PatchError(f"invalid JSON pointer: {pointer!r}")

    parts = []
    for part in pointer[1:].split("/"):
        index = 0
        decoded = []
        while index < len(part):
            char = part[index]
            if char == "~":
                if index + 1 >= len(part) or part[index + 1] not in {"0", "1"}:
                    raise PatchError(f"invalid JSON pointer escape: {pointer!r}")
                decoded.append("~" if part[index + 1] == "0" else "/")
                index += 2
            else:
                decoded.append(char)
                index += 1
        parts.append("".join(decoded))
    return parts


def _list_index(part, length, *, allow_end=False, allow_append=False):
    if allow_append and part == "-":
        return length
    if part == "-":
        raise PatchError("'-' is only valid for array add paths")
    try:
        index = int(part)
    except (TypeError, ValueError):
        raise PatchError(f"invalid array index: {part!r}") from None
    if str(index) != part:
        raise PatchError(f"invalid array index: {part!r}")

    upper_bound = length if allow_end else length - 1
    if index < 0 or index > upper_bound:
        raise PatchError(f"array index out of bounds: {part!r}")
    return index


def _resolve_parent(document, parts):
    target = document
    for part in parts[:-1]:
        if isinstance(target, list):
            target = target[_list_index(part, len(target))]
        elif isinstance(target, dict):
            if part not in target:
                raise PatchError(f"path does not exist: {part!r}")
            target = target[part]
        else:
            raise PatchError(f"cannot traverse into {type(target).__name__}")
    return target, parts[-1] if parts else None


def _get(document, parts):
    target = document
    for part in parts:
        if isinstance(target, list):
            target = target[_list_index(part, len(target))]
        elif isinstance(target, dict):
            if part not in target:
                raise PatchError(f"path does not exist: {part!r}")
            target = target[part]
        else:
            raise PatchError(f"cannot traverse into {type(target).__name__}")
    return target


def _add(document, parts, value):
    if not parts:
        return copy.deepcopy(value)

    target, key = _resolve_parent(document, parts)
    value = copy.deepcopy(value)
    if isinstance(target, list):
        target.insert(_list_index(key, len(target), allow_end=True, allow_append=True), value)
    elif isinstance(target, dict):
        target[key] = value
    else:
        raise PatchError(f"cannot add into {type(target).__name__}")
    return document


def _replace(document, parts, value):
    if not parts:
        return copy.deepcopy(value)

    target, key = _resolve_parent(document, parts)
    value = copy.deepcopy(value)
    if isinstance(target, list):
        target[_list_index(key, len(target))] = value
    elif isinstance(target, dict):
        if key not in target:
            raise PatchError(f"path does not exist: {key!r}")
        target[key] = value
    else:
        raise PatchError(f"cannot replace in {type(target).__name__}")
    return document


def _remove(document, parts):
    if not parts:
        return None

    target, key = _resolve_parent(document, parts)
    if isinstance(target, list):
        target.pop(_list_index(key, len(target)))
    elif isinstance(target, dict):
        if key not in target:
            raise PatchError(f"path does not exist: {key!r}")
        target.pop(key)
    else:
        raise PatchError(f"cannot remove from {type(target).__name__}")
    return document


def _take(document, parts):
    if not parts:
        return None, document

    target, key = _resolve_parent(document, parts)
    if isinstance(target, list):
        return target.pop(_list_index(key, len(target))), document
    if isinstance(target, dict):
        if key not in target:
            raise PatchError(f"path does not exist: {key!r}")
        return target.pop(key), document
    raise PatchError(f"cannot remove from {type(target).__name__}")


def _is_prefix(prefix, parts):
    return len(prefix) < len(parts) and parts[:len(prefix)] == prefix


def apply_patch(document, operations):
    result = copy.deepcopy(document)
    for operation in operations:
        try:
            op = operation["op"]
            path = _parse_pointer(operation["path"])
        except KeyError as exc:
            raise PatchError(f"missing operation member: {exc.args[0]}") from None

        if op == "add":
            if "value" not in operation:
                raise PatchError("add operation requires a value")
            result = _add(result, path, operation["value"])
        elif op == "replace":
            if "value" not in operation:
                raise PatchError("replace operation requires a value")
            result = _replace(result, path, operation["value"])
        elif op == "remove":
            result = _remove(result, path)
        elif op == "move":
            if "from" not in operation:
                raise PatchError("move operation requires a from path")
            from_path = _parse_pointer(operation["from"])
            if from_path == path or _is_prefix(from_path, path):
                raise PatchError("cannot move a value into itself")
            value, result = _take(result, from_path)
            result = _add(result, path, value)
        elif op == "copy":
            if "from" not in operation:
                raise PatchError("copy operation requires a from path")
            value = copy.deepcopy(_get(result, _parse_pointer(operation["from"])))
            result = _add(result, path, value)
        else:
            raise PatchError(f"unsupported operation: {op!r}")
    return result
